const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={spark:'<path d="m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6Z"/>',chat:'<path d="M4 4h16v12H9l-5 4V4Z"/><path d="M8 8h8M8 12h5"/>',pen:'<path d="m14 4 6 6-10 10H4v-6L14 4Z"/><path d="m11 7 6 6"/>',layout:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 9h18M9 9v12"/>',tag:'<path d="M3 3h9l9 9-9 9-9-9V3Z"/><circle cx="8" cy="8" r="1"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',file:'<path d="M6 3h8l4 4v14H6Z"/><path d="M14 3v5h4M9 12h6M9 16h6"/>',grid:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M3 14h18M9 4v16"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[k]||paths.spark}</svg>`;
const download=(name,content,type='application/json')=>{const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.hidden=true;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const read=readPreference;
const link=(url,label)=>/^https:\/\//.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';
const previewLabel='<span class="lesson-demo">GPU training workspace</span>';
const size=rows=>`${rows.length} ${rows.length===1?'example':'examples'}`;
export const teachingShell=()=>'<main class="teach-page lesson-page" id="teach-page"></main>';

export function mountTeaching(root,props){
  let alive=true,dispose=null;
  async function open(){root.innerHTML='<div class="empty card" role="status">Opening your teaching project…</div>';try{await (props.loadWorkspace||loadWorkspace)();if(alive)dispose=mountLesson(root,props);}catch(e){if(alive)root.innerHTML=`<section class="empty card"><h1>Your workspace could not be opened.</h1><p>${esc(accountError(e))}</p><button class="button primary" data-workspace-retry>Try again</button><a class="inline-link" href="/my-models">My models</a></section>`;}}
  const retry=e=>{if(e.target.closest('[data-workspace-retry]'))void open();};root.addEventListener('click',retry);void open();
  return ()=>{alive=false;dispose?.();root.removeEventListener('click',retry);};
}

function mountLesson(root,{catalog,hardware,getAccount=defaultGetAccount,client=trainingClient,saveProject=saveTeachingProject}){
  const events=new AbortController(),params=new URLSearchParams(location.search);
  let d=upgradeDraft(),alive=true,error='',notice='',saving=false,generating=false,running=false,index=0,page=0,filter='all',search='',timer=null,editing=null,capabilities=null,capabilityError='',job=null,polling=false,pollDelay=2500,persistQueue=Promise.resolve(),historyJobs=null,historyLoading=false,historyError='';
  try{
    const id=params.get('draft'),existing=id?teachingProjects().find(x=>x.id===id):null;
    if(existing){d=upgradeDraft(existing);if(existing.flowVersion!==2)notice='Your saved examples are preserved. Review the full dataset and separate test questions in this updated flow.';}else if(id)notice='This project is not available in your current workspace. You can start a new one or open My models.';
    if(!existing)d.modelId=params.get('model')||(location.pathname.startsWith('/customize/')?decodeURIComponent(location.pathname.split('/')[2]||''):'');
  }catch(e){error=accountError(e);}
  const config=confirmedConfiguration(read('macfit.recommendation.profile',null),configurations(hardware));
  d.deviceConfirmed=!!config;d.deviceId=config?.id||'';d.delivery='adapter';
  const availableModels=()=>Array.isArray(capabilities?.models)?capabilities.models.map(m=>({...catalog.models.find(c=>c.id===m.id||c.hf_id===m.repo_id),...m,hf_id:m.repo_id,repository_revision:m.revision})):[];
  const model=()=>availableModels().find(m=>m.id===d.modelId);
  const generationModel=()=>d.generationModelId||availableModels().find(m=>m.id==='qwen3-4b')?.id||availableModels()[0]?.id||'';
  const syncBusy=()=>{generating=d.gpuJob?.kind==='generation'&&activeJob(d.gpuJob);running=d.gpuJob?.kind==='training'&&activeJob(d.gpuJob);};
  syncBusy();
  const stage=()=>Math.min(d.stage,4);
  const busy=()=>saving||generating||running;
  const input=(id,label,value,placeholder,field,rows=3)=>`<label for="${id}">${label}</label><textarea id="${id}" data-field="${field}" rows="${rows}" maxlength="${field==='source'?12000:6000}" placeholder="${esc(placeholder)}">${esc(value)}</textarea>`;
  const heading=(eyebrow,title,desc)=>`<div class="lesson-heading"><span class="eyebrow">${eyebrow}</span><h1 tabindex="-1" id="lesson-title">${title}</h1><p>${desc}</p></div>`;
  const action=(name,text,style='primary',extra='')=>`<button class="button ${style}" data-lesson="${name}" ${extra}>${text}</button>`;
  const signInNotice=()=>'<p class="lesson-small">Sign in with Google to submit GPU jobs. You can edit examples and import a dataset without signing in.</p><button class="button secondary" data-action="google-signin">Sign in with Google</button>';
  function serviceNotice(){return capabilityError?`<p class="lesson-error" role="alert">${esc(capabilityError)}</p>${action('refresh-service','Check GPU service','secondary')}`:!capabilities?'<p role="status">Checking the GPU service…</p>':!capabilities.available?`<p class="lesson-error" role="status">${esc(capabilities.reason||'The GPU worker is unavailable. Your draft can still be edited.')}</p>${action('refresh-service','Check GPU service','secondary')}`:'';}
  function generationControls(purpose='preview'){const models=availableModels(),selected=generationModel(),supported=models.some(m=>m.id===selected),signedIn=!!getAccount().user,canGenerate=signedIn&&capabilities?.available&&capabilities?.generation&&supported;return `<section class="lesson-guided card"><h2>${purpose==='dataset'?'Generate the full dataset on the GPU.':'Generate a preview on the GPU.'}</h2>${serviceNotice()}<label for="lesson-generation-model">Generation model<select id="lesson-generation-model" ${!models.length?'disabled':''}>${!supported?`<option value="" selected disabled>${d.generationModelId?'Previous model unavailable — choose another':capabilities?'No generation models available':'Loading supported models…'}</option>`:''}${models.map(m=>`<option value="${esc(m.id)}" ${m.id===selected?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><p class="lesson-small">This model drafts your examples. You choose the training base model separately in Train & test.</p><p class="lesson-small">Your task, reference notes${purpose==='dataset'?' and corrected examples':''} are sent to the connected GPU server only when you start.</p>${!signedIn?signInNotice():''}${action(purpose==='dataset'?'build-dataset':'generate-preview',purpose==='dataset'?'Generate dataset on GPU':'Generate three examples','primary',!canGenerate?'disabled':'')}</section>`;}
  function jobBanner(){const ref=d.gpuJob;if(!ref)return '';const status=job?.status||ref.status,labels={submitting:'Checking submission',queued:'Queued',running:'Running',cancelling:'Cancellation requested',succeeded:'Completed',failed:'Failed',cancelled:'Cancelled'},p=job?.progress;return `<div class="lesson-building" role="status"><div><strong>${ref.kind==='generation'?'GPU generation':'GPU training'} · ${esc(labels[status]||status)}</strong><p>${esc(job?.stage||ref.stage||'Waiting for the service')}</p>${p&&Number.isFinite(p.completed)&&Number.isFinite(p.total)&&p.total>0?`<p>${p.completed} / ${p.total} ${esc(p.unit||'steps')}</p>`:''}${job?.error?.message||ref.failureMessage?`<p class="lesson-error">${esc(job?.error?.message||ref.failureMessage)}</p>`:''}${ref.jobId?`<small>Job ${esc(ref.jobId)}</small>`:''}<div class="lesson-result-actions">${action('refresh-job','Check status','secondary',polling?'disabled':'')}${activeJob(ref)?action('cancel-job',status==='cancelling'?'Waiting for cancellation…':'Cancel job','secondary',!ref.jobId||status==='cancelling'?'disabled':''):ref.kind==='generation'?action('clear-job','Continue editing','secondary'):''}</div></div></div>`;}
  const historyProject=()=>d.gpuProjectId||d.gpuJob?.projectId||(validUUID(d.id)?d.id:null);
  async function loadHistory(){if(historyLoading)return;const projectId=historyProject(),owner=getAccount().user?.uid;if(!projectId||!owner)return;historyLoading=true;historyError='';paint();try{const result=await client.list({projectId},{signal:events.signal});if(!alive||getAccount().user?.uid!==owner)return;if(!Array.isArray(result.items))throw Error('Saved jobs could not be read. Please try again.');historyJobs=result.items.filter(row=>row?.kind==='training'&&row.project_id===projectId&&validUUID(row.id)&&validUUID(row.request_id)&&['queued','running','cancelling','succeeded','failed','cancelled'].includes(row.status));}catch(e){if(alive&&getAccount().user?.uid===owner)historyError=trainingError(e);}finally{historyLoading=false;if(alive)paint();}}
  function historyMarkup(){if(!historyProject()||!getAccount().user)return '';return `<section class="card lesson-downloads lesson-history"><div><h2>Saved training runs.</h2><p>Results and downloads for this project remain available when GPU training is paused.</p><p class="lesson-small">Shows training runs among this project’s 50 most recent GPU jobs.</p></div>${action('load-history',historyLoading?'Loading saved runs…':historyJobs?'Refresh saved runs':'Load saved training runs','secondary',historyLoading?'disabled':'')}${historyError?`<p class="lesson-error" role="alert">${esc(historyError)}</p>`:''}${historyJobs?.length===0?'<p>No saved training runs were returned for this account and project.</p>':''}${(historyJobs||[]).map(saved=>{const samples=Array.isArray(saved.result?.evaluation?.samples)?saved.result.evaluation.samples.filter(row=>row&&typeof row.question==='string'):[],artifacts=saved.status==='succeeded'&&Array.isArray(saved.artifacts)?saved.artifacts:[];return `<details class="card" data-history="${esc(saved.id)}"><summary>${esc(saved.created_at||'Saved run')} · ${esc(saved.base_model?.repo_id||'Training job')} · ${esc(saved.status)}</summary><p class="lesson-small">Job ${esc(saved.id)}</p>${saved.error?.message?`<p class="lesson-error">${esc(saved.error.message)}</p>`:''}${samples.length?`<h3>Actual held-out outputs</h3>${samples.map((sample,index)=>`<details data-history="${esc(saved.id)}-${index}"><summary>${esc(sample.question)}</summary><div class="lesson-result-columns"><div><span>Original model</span><p class="lesson-preserve">${esc(sample.before??'No output returned')}</p></div><div><span>Trained adapter</span><p class="lesson-preserve">${esc(sample.after??'No output returned')}</p></div></div><p class="lesson-preserve"><strong>Your expected answer</strong><br/>${esc(sample.expected)}</p></details>`).join('')}`:'<p>No held-out outputs were returned for this run.</p>'}${artifacts.length?`<p>The adapter requires its pinned base model. Read the included usage notes before running it.</p><div class="lesson-result-actions">${artifacts.map(a=>action('download-artifact',esc(a.name),'secondary',`data-job="${esc(saved.id)}" data-artifact="${esc(a.id)}"`)).join('')}</div>`:''}</details>`;}).join('')}</section>`;}
  async function loadCapabilities(){try{const result=await client.capabilities({signal:events.signal});if(!alive)return;if(!Array.isArray(result.models))throw Error('The GPU service returned an invalid model registry.');capabilities=result;capabilityError='';}catch(e){if(!alive)return;capabilityError=trainingError(e);}const focusId=document.activeElement?.id;paint();if(focusId&&/^[a-z0-9-]+$/i.test(focusId))root.querySelector('#'+focusId)?.focus({preventScroll:true});}
  function requireJobOwner(){const uid=getAccount().user?.uid;if(!uid)throw Error('Sign in with Google to submit or open GPU jobs.');if(d.gpuJob?.ownerUid&&d.gpuJob.ownerUid!==uid)throw Error('This job belongs to another account. Reopen it in its owner’s account.');return uid;}
  function submissionPayload(){const ref=d.gpuJob;return {request_id:ref.requestId,project_id:ref.projectId,kind:ref.kind,input:ref.kind==='generation'?generationInput(d,ref.modelId,ref.purpose):trainingInput(d,ref.modelId,ref.preset)};}
  function schedulePoll(){clearTimeout(timer);if(alive&&activeJob(d.gpuJob))timer=setTimeout(()=>void checkJob(),pollDelay);}
  async function acceptJob(value){if(job&&value.id===job.id&&((terminalJob(job)&&!terminalJob(value))||(job.status==='cancelling'&&['queued','running'].includes(value.status))||Date.parse(value.updated_at)<Date.parse(job.updated_at)))return;const previous=d.gpuJob,changed=previous.jobId!==value.id||previous.status!==value.status||previous.stage!==value.stage;d.gpuJob=jobReference(value,previous);job=value;syncBusy();let applied=false;if(value.status==='succeeded'&&value.kind==='generation')applied=applyGenerationResult(d,value);if(value.kind==='training')d.status='training-'+value.status;if(changed||applied){try{await persist({quiet:true});}catch(e){notice='The job is recorded on the GPU server, but this project update could not be saved: '+trainingError(e);}}if(!alive)return;if(value.status==='failed')error=value.error?.message||'The GPU job failed. Your reviewed data is preserved.';if(applied)notice='Real generated examples are ready. Review every new answer before approving it.';paint();}
  async function checkJob(){if(polling||!d.gpuJob)return;clearTimeout(timer);polling=true;const requestId=d.gpuJob.requestId;try{requireJobOwner();const ref=d.gpuJob;if(ref.status==='failed'&&!ref.jobId){paint();return;}const value=ref.jobId?await client.get(ref.jobId,{signal:events.signal}):await recoverSubmission(client,submissionPayload(),{signal:events.signal});if(!alive||d.gpuJob?.requestId!==requestId)return;pollDelay=2500;error='';await acceptJob(value);}catch(e){if(!alive||d.gpuJob?.requestId!==requestId)return;error=trainingError(e);pollDelay=Math.min(pollDelay*2,30000);if(e.status>=400&&e.status<500&&![401,403,429].includes(e.status)&&!d.gpuJob.jobId){Object.assign(d.gpuJob,{status:'failed',stage:'submission rejected',failureMessage:error});syncBusy();try{await persist({quiet:true});}catch{}}paint();}finally{polling=false;if(alive){paint();schedulePoll();}}}
  async function beginJob(kind,purpose){if(polling)throw Error('Wait for the current status check to finish, then try again.');if(activeJob(d.gpuJob))throw Error('Your current GPU job is still active. Wait for it or cancel it first.');const ownerUid=requireJobOwner();if(!capabilities?.available||!capabilities?.[kind])throw Error('The GPU service is unavailable. Check its status and try again.');const modelId=kind==='generation'?generationModel():d.modelId;if(!availableModels().some(m=>m.id===modelId))throw Error('Choose a model supported by this GPU service.');const preset=d.trainingPreset||'quick',input=kind==='generation'?generationInput(d,modelId,purpose):trainingInput(d,modelId,preset);const previous={job:d.gpuJob,stage:d.stage,status:d.status};d.id ||= crypto.randomUUID();d.gpuProjectId ||= validUUID(d.id)?d.id:crypto.randomUUID();d.gpuJob={requestId:crypto.randomUUID(),projectId:d.gpuProjectId,kind,modelId,ownerUid,purpose:kind==='generation'?purpose:undefined,preset:kind==='training'?preset:undefined,jobId:null,status:'submitting',stage:'Submitting',applied:false};if(kind==='generation'){d.generationModelId=modelId;d.generationTarget=purpose==='dataset'?input.target_count:d.generationTarget;}else{d.stage=5;d.status='training-submitting';}job=null;syncBusy();try{await persist();}catch(e){d.gpuJob=previous.job;d.stage=previous.stage;d.status=previous.status;syncBusy();throw e;}if(!alive)return;notice='';paint(true);polling=true;try{const value=await client.create({request_id:d.gpuJob.requestId,project_id:d.gpuJob.projectId,kind,input},{signal:events.signal});if(alive)await acceptJob(value);}catch(e){if(!alive)return;error=trainingError(e);if(e.status>=400&&e.status<500&&![401,403,429].includes(e.status)){Object.assign(d.gpuJob,{status:'failed',stage:'submission rejected',failureMessage:error});syncBusy();try{await persist({quiet:true});}catch{}}else notice='The request may already be accepted. Checking this same request will not create a second job.';}finally{polling=false;if(alive){paint();schedulePoll();}}}
  async function cancelJob(){if(!d.gpuJob?.jobId)throw Error('Check the pending submission before cancelling it.');requireJobOwner();const value=await client.cancel(d.gpuJob.jobId,{signal:events.signal});if(!alive)return;await acceptJob(value);schedulePoll();}
  const next=(text,back=true)=>`<div class="lesson-bottom">${back?action('back','← Back','text'): '<span>No code. No dataset required to start.</span>'}${action('next',text+' '+icon('arrow'))}</div>`;
  function summary(){return `<aside class="lesson-sidebar"><span class="eyebrow">YOUR TEACHING PROJECT</span><h2>${esc(d.name||taskTypes[d.task]?.title||'A model that works your way')}</h2><p class="lesson-preserve">${esc(d.goal||'One clear task. A few examples. Your own way of working.')}</p><dl><div><dt>Language</dt><dd>${esc({en:'English',zh:'Chinese',multi:'Multiple languages'}[d.language])}</dd></div><div><dt>Starting material</dt><dd>${esc(sourceModes[d.sourceMode]?.title||'Not selected')}</dd></div><div><dt>Preview examples</dt><dd>${d.seeds.filter(e=>e.approved).length} / ${d.seeds.length} approved</dd></div><div><dt>Full dataset</dt><dd>${d.datasetBuilt?size(d.examples):'Not prepared yet'}</dd></div></dl>${d.source?`<details><summary>Your reference notes</summary><p class="lesson-preserve">${esc(d.source)}</p></details>`:''}<div class="lesson-sidebar-note">${icon('shield')}<p>Saving ${getAccount().user?'uploads this project and its examples to your private account':'keeps your project in this browser'}. Only you decide when to start.</p></div></aside>`;}
  function shell(content){return `<div class="lesson-topbar"><a href="/" class="back-link">← MacFit</a><span class="lesson-project-name">${esc(d.name||'New teaching project')}</span>${previewLabel}<button class="teach-save" data-lesson="save" ${saving||generating||running?'disabled':''}>${saving?'Saving…':getAccount().user?'Save to account':'Save draft'}</button></div><nav class="lesson-steps" aria-label="Teaching steps"><ol>${['Your task','Your material','Teach by example','Prepare dataset','Train & test'].map((name,i)=>`<li class="${stage()===i?'current':stage()>i?'complete':''}" ${stage()===i?'aria-current="step"':''}><button data-lesson="step" data-step="${i}" ${i>d.stage||busy()?'disabled':''}><span>${stage()>i?icon('check'):String(i+1).padStart(2,'0')}</span>${name}</button></li>`).join('')}</ol></nav><div class="lesson-notices" aria-live="polite">${notice?`<p role="status">${esc(notice)}</p>`:''}${error?`<p class="lesson-error" role="alert">${esc(error)}</p>`:''}</div>${d.gpuJob?.kind==='generation'?jobBanner():''}${d.gpuJob?.kind==='training'&&d.stage!==5?`<div class="lesson-result-actions">${action('view-job-results','View saved job results','secondary')}</div>`:''}${content}${historyMarkup()}<p class="lesson-preview-note">GPU jobs run on the connected training server and continue when you leave this page. Generated examples need your review. Training does not guarantee better answers.</p>`;}
  function taskStep(){return heading('START WITH SOMETHING USEFUL','What should your model<br/><em>learn to do?</em>','Pick one task. We’ll help you turn your idea into examples, then a reviewed dataset.')+`<div class="lesson-layout"><section><div class="lesson-tasks">${Object.entries(taskTypes).map(([id,t])=>`<button class="lesson-task ${d.task===id?'selected':''}" data-lesson="task" data-task="${id}" aria-pressed="${d.task===id}"><span>${icon(t.icon)}</span><strong>${esc(t.title)}</strong><p>${esc(t.description)}</p><i>${d.task===id?'✓':''}</i></button>`).join('')}</div><div class="lesson-form">${input('lesson-goal','Describe a good result',d.goal,'For example: Turn meeting notes into action items with an owner and a due date.','goal')}<div class="lesson-field-hint"><span>Be specific about the output you want.</span>${d.task&&d.task!=='custom'?'<button data-lesson="use-preset">Try an example task</button>':''}</div><div class="lesson-form-row"><label for="lesson-language">Main language<select id="lesson-language" data-field="language">${Object.entries({en:'English',zh:'Chinese',multi:'Multiple languages'}).map(([id,label])=>`<option value="${id}" ${d.language===id?'selected':''}>${label}</option>`).join('')}</select></label><label for="lesson-name">Project name <small>Optional</small><input id="lesson-name" data-field="name" maxlength="80" value="${esc(d.name)}" placeholder="My meeting notes assistant"></label></div></div>${next('Choose my starting material',false)}</section><aside class="lesson-welcome"><div class="lesson-welcome-art"><span>${icon('pen')}</span><p>A little guidance.<br/><em>A different kind of AI.</em></p><div class="lesson-paper"><small>YOU SHOW IT</small><p>“This is the answer I want.”</p><span>✓ Clear examples</span></div></div><h2>You don’t need a dataset yet.</h2><p>Start with an idea, a few notes, or examples you already have. We’ll build the teaching material together.</p><div class="lesson-mini-roadmap"><span>Preview</span><i>→</i><span>Refine</span><i>→</i><span>Prepare</span><i>→</i><span>Train</span></div></aside></div>`;}
  function importArea(){return `<div class="lesson-import-zone">${icon('grid')}<h2>Bring your own examples.</h2><p>Choose JSON or JSONL with input/answer pairs. Your file is read locally before you save.</p><label class="button secondary lesson-file-label">Choose a dataset<input id="lesson-dataset-file" type="file" accept=".json,.jsonl,application/json,application/x-ndjson"></label>${d.datasetName?`<span class="lesson-file-name">${esc(d.datasetName)} · ${size(d.examples)}</span>`:''}<span class="lesson-small">Up to 500 examples · 2 MB. A new file replaces this working dataset.</span></div><details class="lesson-advanced"><summary>Supported dataset formats</summary><p>Use question/answer or input/output fields, or one user/assistant turn with an optional system message. Multi-turn and tool conversations need a separate conversion.</p><pre>{"question":"Your input","answer":"Your ideal answer"}</pre>${action('template','Download a format example','text')}</details>`;}
  function materialStep(){return heading('USE WHAT YOU HAVE','No dataset?<br/><em>You can still start.</em>','Choose a starting point. You’ll see a small preview before preparing the full dataset.')+`<div class="lesson-layout"><section><div class="lesson-source-options">${Object.entries(sourceModes).map(([id,m])=>`<button data-lesson="source-mode" data-source-mode="${id}" class="lesson-source ${d.sourceMode===id?'selected':''}" aria-pressed="${d.sourceMode===id}"><span>${icon({guided:'spark',reference:'file',import:'grid'}[id])}</span><div><strong>${m.title}</strong><p>${m.description}</p></div><i>${d.sourceMode===id?'✓':''}</i></button>`).join('')}</div>${d.sourceMode==='guided'?`<section class="lesson-guided card"><span class="eyebrow">WE’LL START SMALL</span><h2>Three examples to find your direction.</h2><p>Preview the questions and ideal answers, correct anything you dislike, then use those corrections when building your dataset.</p><div class="lesson-chips"><span>Everyday request</span><span>A different situation</span><span>Missing information</span></div><p class="lesson-small">Generate three real examples on the GPU, or write your own. Review the facts and language before approving them.</p></section>`:d.sourceMode==='reference'?`<section class="lesson-reference card">${input('lesson-reference','Paste the material it should learn from',d.source,'Your policy, a writing sample, instructions, or a few facts.','source',7)}<div class="lesson-reference-footer"><label class="lesson-file-label">${icon('file')} Import text<input id="lesson-reference-file" type="file" accept=".txt,.md,text/plain,text/markdown"></label><span>${d.referenceName?esc(d.referenceName):'TXT / Markdown · up to 12,000 characters'}</span></div><p class="lesson-small">GPU generation uses these notes as source material. Review each generated answer for accuracy.</p></section>`:importArea()}${d.sourceMode!=='import'?generationControls():''}${next(d.sourceMode==='import'?'Preview my examples':'Write three examples myself')}</section>${summary()}</div>`;}
  function previewStep(){index=Math.min(index,Math.max(0,d.seeds.length-1));const e=d.seeds[index];return heading('TEACH THE DIRECTION FIRST','Show it what<br/><em>a good answer looks like.</em>','These first examples establish your direction. They are not the complete training dataset.')+`<div class="lesson-layout"><section><div class="lesson-preview-tabs" role="group" aria-label="Preview examples">${d.seeds.map((x,i)=>`<button data-lesson="seed-tab" data-index="${i}" class="${index===i?'selected':''}">${x.approved?'✓':'0'+(i+1)} ${['First example','Second example','Third example'][i]||'Example '+(i+1)}</button>`).join('')}</div>${e?`<section class="lesson-seed card"><div class="lesson-seed-heading"><span>EXAMPLE ${index+1} OF ${d.seeds.length}</span><span id="lesson-seed-status" class="lesson-status ${e.approved?'good':''}">${e.approved?'Approved':'Needs your review'}</span></div><div class="lesson-seed-body"><label for="lesson-seed-question">What someone asks</label><textarea id="lesson-seed-question" data-seed="question" maxlength="12000" rows="3">${esc(e.question)}</textarea><label for="lesson-seed-answer">The answer you want</label><textarea id="lesson-seed-answer" data-seed="answer" maxlength="24000" rows="6">${esc(e.answer)}</textarea>${e.system?`<details><summary>Imported system instruction</summary><p>${esc(e.system)}</p></details>`:''}<div class="lesson-feedback-note">${icon('pen')}<p>Edit the answer directly. Your exact correction becomes a reference for the next batch of examples.</p></div><div class="lesson-seed-actions"><span id="lesson-seed-count">${d.seeds.filter(x=>x.approved).length} / ${d.seeds.length} approved</span>${action('approve-seed',e.approved?'Approved ✓':'This is the answer I want '+icon('check'))}</div></div></section>`:'<div class="empty card">No preview examples. Go back and choose your material.</div>'}<p class="lesson-inline-note">${d.sourceMode==='import'?'These are the first three rows of your file. The remaining rows are reviewed in the next step.':'Review each answer for factual accuracy and the behavior you want. GPU-generated drafts are not automatically approved.'}</p>${next('Prepare the full dataset')}</section>${summary()}</div>`;}
  function dataRows(){const report=checkDataset(d);let rows=d.examples;if(filter==='pending')rows=rows.filter(e=>!e.approved);if(filter==='issues')rows=rows.filter(e=>report.rowProblems.has(e.id));if(filter==='approved')rows=rows.filter(e=>e.approved&&!report.rowProblems.has(e.id));const pages=Math.max(1,Math.ceil(rows.length/6));page=Math.min(page,pages-1);return {all:rows,visible:rows.slice(page*6,page*6+6),pages,report};}
  function dataTable(){const {visible,all,pages,report}=dataRows();return `<div class="lesson-table-toolbar"><div class="lesson-table-filters" aria-label="Dataset filters">${[['all','All'],['pending','Needs review'],['issues','Issues'],['approved','Approved']].map(([id,label])=>`<button data-lesson="filter" data-filter="${id}" class="${filter===id?'selected':''}">${label}</button>`).join('')}</div>${action('approve-page','Approve this page','secondary',!visible.length?'disabled':'')}</div>${d.sourceMode==='import'?`<details class="lesson-import-review"><summary>Already reviewed your imported file?</summary><p>If you have checked every answer yourself, mark structurally valid rows reviewed in one step. Flagged rows remain blocked.</p>${action('approve-import','I reviewed all valid imported rows','secondary')}</details>`:''}<div class="lesson-table-wrap"><table class="lesson-data-table"><thead><tr><th>Teaching example</th><th>Desired answer</th><th>Review</th></tr></thead><tbody>${visible.map(e=>`<tr class="${report.rowProblems.has(e.id)?'has-issue':''}"><td><button class="lesson-row-edit" data-lesson="edit-row" data-row="${esc(e.id)}"><span>${esc(e.question)}</span><small>${e.origin==='imported'?'Imported':e.origin==='gpu-generated'?'GPU generated':e.origin==='demo-expanded'?'Legacy example':e.origin==='user-edited'?'Your correction':'Your teaching example'}</small></button></td><td><button class="lesson-answer-preview" data-lesson="edit-row" data-row="${esc(e.id)}">${esc(e.answer||'Add an answer…')}</button></td><td><span class="lesson-status ${report.rowProblems.has(e.id)?'issue':e.approved?'good':''}">${report.rowProblems.has(e.id)?'Needs a fix':e.approved?'Approved':'Review'}</span><button class="lesson-row-action" data-lesson="edit-row" data-row="${esc(e.id)}" aria-label="Edit example ${esc(e.question.slice(0,60))}">Edit ↗</button></td></tr>`).join('')||'<tr><td colspan="3" class="lesson-empty-row">No examples in this view.</td></tr>'}</tbody></table></div><div class="lesson-table-footer"><span>${all.length?`${page*6+1}–${Math.min((page+1)*6,all.length)}`:'0'} of ${all.length} examples</span><div><button data-lesson="page" data-direction="-1" ${page===0?'disabled':''}>← Previous</button><span>${page+1} / ${pages}</span><button data-lesson="page" data-direction="1" ${page>=pages-1?'disabled':''}>Next →</button></div></div>`;}
  function testSection(){return `<section class="lesson-tests card"><div class="lesson-section-title"><div><span class="eyebrow">KEPT OUT OF TRAINING</span><h2>Give it a few new questions.</h2><p>These checks help you compare the original and trained model fairly.</p></div>${!d.evaluationSamples.length?action('suggest-tests','Suggest test questions','secondary'):action('add-test','+ Add test','text')}</div>${d.evaluationSamples.length?`<div class="lesson-test-list">${d.evaluationSamples.map((e,i)=>`<article><div><span>TEST ${i+1}</span><strong>${esc(e.question||'New test question')}</strong><p>${esc(e.answer||'What should a good answer say?')}</p></div><span class="lesson-status ${e.approved?'good':''}">${e.approved?'Approved':'Review'}</span><button class="lesson-row-action" data-lesson="edit-test" data-row="${esc(e.id)}">Edit ↗</button><button class="lesson-text-action" data-lesson="approve-test" data-row="${esc(e.id)}" ${e.approved?'disabled':''}>${e.approved?'✓':'Approve'}</button></article>`).join('')}</div>`:'<p class="lesson-small">Keep at least three separate questions. More varied test questions give a more useful evaluation.</p>'}<p class="lesson-small">Suggested tests are illustrative. Review every expected answer; the system cannot verify your private facts.</p></section>`;}
  function datasetStep(){const r=checkDataset(d);return heading('A PREVIEW IS JUST THE BEGINNING','Build your teaching set.<br/><em>Make every example count.</em>','Expand your corrected examples, review the complete dataset, and keep test questions separate.')+`<div class="lesson-dataset-banner ${d.datasetStale?'stale':''}"><div><span>${icon('grid')}</span><div><strong>${d.datasetStale?'Your teaching direction changed':d.datasetBuilt?'Your full dataset is ready to review':'Your preview is approved'}</strong><p>${d.datasetStale?'Review the preview again, then rebuild before training.':d.datasetBuilt?'Check every row or approve a page you have reviewed. Fix flagged issues before continuing.':'Now prepare the full set. Approving three samples does not start training.'}</p></div></div>${!d.datasetBuilt||d.datasetStale?`<div class="lesson-build-actions">${d.sourceMode!=='import'?`<label for="lesson-count">Dataset size<select id="lesson-count"><option value="12" ${d.generationTarget===12?'selected':''}>12 examples</option><option value="24" ${d.generationTarget===24?'selected':''}>24 examples</option><option value="48" ${d.generationTarget===48?'selected':''}>48 examples</option></select></label>`:''}${d.sourceMode==='import'?action('build-dataset','Check my full dataset','primary',generating?'disabled':''):''}</div>`:action('export-data','Export dataset','secondary')}</div>${d.sourceMode!=='import'&&(!d.datasetBuilt||d.datasetStale)?generationControls('dataset'):''}${generating?'<div class="lesson-building" role="status"><span class="loading-indicator"></span><div><strong>Preparing your review table…</strong><p>The GPU is generating new examples using your corrected seeds.</p></div></div>':''}${d.datasetBuilt?`<div class="lesson-metrics"><div><strong>${r.count}</strong><span>Teaching examples</span></div><div><strong>${r.approved}<small> / ${r.count}</small></strong><span>Reviewed & approved</span></div><div><strong>${r.issues.length}</strong><span>Data issues</span></div><div><strong>${r.tests}</strong><span>Separate test questions</span></div></div><section class="lesson-data-card card"><div class="lesson-section-title"><div><h2>Your complete dataset</h2><p>${d.sourceMode==='import'?'All imported rows are kept. The initial preview is only a subset.':'Generated rows are proposed training examples. Review their facts and task coverage before approving them.'}</p></div><span class="lesson-status">${d.sourceMode==='import'?'Imported data':'GPU-generated data'}</span></div>${dataTable()}</section>${r.issues.length?`<div class="lesson-check-warning" role="status"><strong>${r.issues.length} ${r.issues.length===1?'issue needs':'issues need'} attention</strong><ul>${r.issues.slice(0,5).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${testSection()}<section class="lesson-readiness"><div><span>${icon(r.ready?'check':'shield')}</span><div><h2>${r.ready&&!d.datasetStale?'Ready for training review':'A few things to review first'}</h2><p>${d.datasetStale?'Rebuild the dataset after reviewing your changed examples.':r.pending?`${r.pending} teaching examples still need approval.`:r.testIssues[0]||r.testPending?`${r.testIssues[0]||'Approve all test questions.'}`:r.issues[0]||'Structural checks passed. This does not verify factual accuracy or guarantee model quality.'}</p></div></div><label class="lesson-check"><input id="lesson-dataset-confirm" type="checkbox" ${d.datasetConfirmed?'checked':''} ${!r.ready?'disabled':''}> I reviewed the full dataset and the separate test questions.</label></section>${next('Choose model & review training')}`:`<div class="lesson-dataset-empty"><div>${icon('pen')}<h3>Your corrections</h3><p>${d.seeds.length} reviewed preview examples</p></div><span>→</span><div>${icon('grid')}<h3>A full review table</h3><p>Approve rows and fix conflicting answers</p></div><span>→</span><div>${icon('shield')}<h3>Separate checks</h3><p>New questions to test the result</p></div></div><div class="lesson-bottom">${action('back','← Back to preview','text')}</div>`}`;}
  function modelCard(m){const e=modelEvidence(m,d.task,d.language),selected=m.id===d.modelId;return `<article class="lesson-model ${selected?'selected':''}"><div><span class="lesson-model-mark">${esc((m.owner||m.name).slice(0,1))}</span><span>${esc(parameterLabel(m))} parameters</span></div><h3>${esc(m.name)}</h3><p>${esc(e.task?.reason||'Task-specific capability evidence has not been reviewed for this model.')}</p><dl><div><dt>Context</dt><dd>${esc(contextLabel(m))}</dd></div><div><dt>Your language</dt><dd>${e.language?'Publisher-documented':'Not verified'}</dd></div><div><dt>License</dt><dd>${esc(licenseLabel(m.license))}</dd></div></dl>${action('model',selected?'Selected ✓':'Use this model',selected?'primary':'secondary',`data-model="${esc(m.id)}" aria-pressed="${selected}"`)}<details><summary>Capabilities & limits</summary><p>${esc(m.description||'No publisher description recorded.')}</p><p>Publisher claims are not task evaluations. Training compatibility, access requirements, and final device fit must be checked by the connected service.</p>${link(e.task?.source_url||m.description_source_url||'https://huggingface.co/'+m.hf_id,'Publisher source')}</details></article>`;}
  function modelSearch(){if(!search.trim())return '';const ms=availableModels().filter(m=>`${m.name} ${m.repo_id}`.toLowerCase().includes(search.toLowerCase()));return ms.map(m=>`<button class="teach-search-result" data-lesson="model" data-model="${esc(m.id)}"><span>${esc(m.name)}<small>${esc(m.repo_id)}</small></span><span>Supported →</span></button>`).join('')||'<p>No supported training models match this search.</p>';}
  function reviewStep(){const r=checkDataset(d),supported=availableModels();return heading('YOUR DATA. A SUPPORTED STARTING MODEL.','Review the plan.<br/><em>Then start real training.</em>','The server trains a LoRA adapter and evaluates it on your separate test questions.')+`<section class="lesson-model-section"><div class="lesson-section-title"><div><h2>Choose a supported starting model</h2><p>The connected GPU service supports the models below. Other catalog models cannot be submitted here.</p></div><span class="lesson-status">Server model registry</span></div>${serviceNotice()}<div class="lesson-model-grid">${supported.map(modelCard).join('')}</div>${d.modelId&&!model()?'<p class="lesson-error" role="alert">Your previous model is not supported by this training service. Choose a listed model; it will not be changed automatically.</p>':''}</section><div class="lesson-review-layout"><section class="card lesson-final-review"><span class="eyebrow">YOUR TRAINING PLAN</span><label for="lesson-final-name">Model name</label><input id="lesson-final-name" data-field="name" maxlength="80" value="${esc(d.name)}" placeholder="My personal model"><dl><div><dt>Task</dt><dd>${esc(d.goal)}</dd></div><div><dt>Starting model</dt><dd>${esc(model()?.name||'Choose a supported model above')}</dd></div><div><dt>Training data</dt><dd>${r.count} reviewed examples<button data-lesson="step" data-step="3">Review data</button></dd></div><div><dt>Evaluation</dt><dd>${r.tests} held-out questions, run on the base model and trained adapter</dd></div><div><dt>Where training runs</dt><dd>The connected GPU server</dd></div><div><dt>Output</dt><dd>A LoRA adapter and measured evaluation results</dd></div></dl><label for="lesson-training-preset">Training preset<select id="lesson-training-preset"><option value="quick" ${(d.trainingPreset||'quick')==='quick'?'selected':''}>Quick — shorter training run</option><option value="standard" ${d.trainingPreset==='standard'?'selected':''}>Standard — longer training run</option></select></label><p class="lesson-small">An adapter requires its exact base model and a compatible runtime. It is not a standalone Mac application or a ready-to-run GGUF model. Online model hosting is not available in this release.</p>${!getAccount().user?signInNotice():''}<label class="lesson-check"><input id="lesson-run-confirm" type="checkbox"> I reviewed this dataset and authorize uploading it for GPU training and held-out evaluation.</label><div class="lesson-bottom">${action('back','← Dataset','text')}${action('start','Start GPU training '+icon('arrow'),'primary',!getAccount().user||!capabilities?.available||!capabilities?.training||!model()?'disabled':'')}</div></section><aside class="lesson-review-sidebar"><span>${icon('spark')}</span><h2>Train a version.<br/>Keep the original.</h2><ol><li><strong>Check the data</strong><p>The server validates your reviewed input again.</p></li><li><strong>Train an adapter</strong><p>The base model revision stays recorded with the result.</p></li><li><strong>Evaluate fairly</strong><p>Both versions answer the same held-out questions.</p></li><li><strong>Download the output</strong><p>Keep the adapter, configuration, evaluation and usage notes.</p></li></ol><p class="lesson-small">You can leave this page and reopen the saved project to check the job. Email notifications are not enabled.</p>${action('export-brief','Export training brief ↗','text')}</aside></div>`;}
  function workStep(){const ref=d.gpuJob,done=ref?.status==='succeeded',failed=ref?.status==='failed',cancelled=ref?.status==='cancelled',samples=Array.isArray(job?.result?.evaluation?.samples)?job.result.evaluation.samples.filter(e=>e&&typeof e.question==='string'):[],sample=samples[Math.min(index,Math.max(0,samples.length-1))],stats=job?.result?.training,artifacts=job?.status==='succeeded'&&Array.isArray(job.artifacts)?job.artifacts:[];return heading(done?'TRAINING FINISHED':failed?'TRAINING DID NOT FINISH':cancelled?'TRAINING CANCELLED':'YOUR GPU JOB',done?'The adapter is trained.<br/><em>Review the actual answers.</em>':failed?'Keep your data.<br/><em>Review what happened.</em>':cancelled?'The job has stopped.<br/><em>Your dataset is preserved.</em>':'Your reviewed examples.<br/><em>A real training job.</em>',done?'Completion does not establish better quality. Compare both versions on the held-out questions.':'The server owns this job. Refreshing or leaving this page does not stop it.')+`<div class="lesson-work-layout"><section class="card lesson-job"><h2>${esc(d.name||projectName(d))}</h2>${jobBanner()}${stats?`<dl><div><dt>Training steps</dt><dd>${Number.isFinite(stats.steps)?stats.steps:'Not reported'}</dd></div><div><dt>Reported training loss</dt><dd>${Number.isFinite(stats.loss)?stats.loss.toFixed(4):'Not reported'}</dd></div></dl><p class="lesson-small">Training loss is not a quality score.</p>`:''}</section><section class="card lesson-result"><div class="lesson-section-title"><div><span class="eyebrow">ACTUAL HELD-OUT OUTPUTS</span><h2>Compare the same question.</h2></div><span class="lesson-status">${samples.length} completed comparisons</span></div>${samples.length?`<label for="lesson-result-test">Test question<select id="lesson-result-test">${samples.map((e,i)=>`<option value="${i}" ${i===index?'selected':''}>${i+1}. ${esc(e.question.slice(0,75))}</option>`).join('')}</select></label><div class="lesson-result-question">${esc(sample?.question)}</div><div class="lesson-result-columns"><div><span>Original model</span><p>${esc(sample?.before??'No output returned')}</p></div><div><span>Trained adapter</span><p>${esc(sample?.after??'No output returned')}</p></div></div><details><summary>Your expected answer</summary><p class="lesson-preserve">${esc(sample?.expected)}</p></details>`:'<p>Actual base-model and adapter outputs will appear after evaluation completes. No comparison has been returned yet.</p>'}${terminalJob(ref)?`<div class="lesson-result-actions">${action('improve','Review my dataset','secondary')}<a class="button primary" href="/my-models">My models →</a></div>`:''}</section></div>${artifacts.length?`<section class="card lesson-downloads"><div><h2>Your actual training outputs.</h2><p>The adapter requires the pinned base model ${esc(job.base_model?.repo_id)}. Read the included usage notes before running it.</p></div>${artifacts.map(a=>action('download-artifact',esc(a.name),'secondary',`data-artifact="${esc(a.id)}"`)).join('')}</section>`:''}<section class="card lesson-downloads"><div><h2>Keep your reviewed data.</h2><p>Training and held-out questions remain separate.</p></div>${action('export-data','Training dataset','secondary')}${action('export-tests','Test questions','secondary')}</section>`;}
  function paint(focus=false){if(!alive)return;const openHistory=[...root.querySelectorAll('[data-history][open]')].map(element=>element.dataset.history);const oldTitle=root.querySelector('#lesson-title'),hadFocus=oldTitle&&document.activeElement===oldTitle;root.innerHTML=shell([taskStep,materialStep,previewStep,datasetStep,reviewStep,workStep][d.stage]());for(const id of openHistory)if(/^[a-f0-9-]+$/i.test(id))root.querySelector('[data-history="'+id+'"]')?.setAttribute('open','');if(saving||generating||running)root.querySelectorAll('input,textarea,select,[data-lesson]').forEach(el=>{if(!['cancel-job','refresh-job','download-artifact','export-data','export-tests','load-history'].includes(el.dataset.lesson))el.disabled=true;});if(focus||hadFocus){root.querySelector('#lesson-title')?.focus({preventScroll:true});if(focus)window.scrollTo({top:0,behavior:'instant'});}}
  function showError(e){if(!alive)return;error=trainingError(e);paint();root.querySelector('[role="alert"]')?.scrollIntoView({block:'center'});}
  function validateTo(nextStage){return (nextStage>0&&goalError(d))||(nextStage>1&&sourceError(d))||(nextStage>2&&seedError(d))||(nextStage>3&&datasetReadyError(d))||'';}
  async function persist({quiet=false}={}){d.id ||= crypto.randomUUID();d.name ||= projectName(d);if(!quiet){saving=true;paint();}const operation=async()=>{if(!alive)return;const saved=await saveProject(structuredClone(d),d.id);if(!alive)return;Object.assign(d,{id:saved.id,updatedAt:saved.updatedAt,_ownerUid:saved._ownerUid,_cloudRevision:saved._cloudRevision});history.replaceState({},'','/teach?draft='+encodeURIComponent(d.id));if(!quiet)notice='Saved to '+workspaceLocation()+'.';};const pending=persistQueue.then(operation,operation);persistQueue=pending.catch(()=>{});try{await pending;}finally{if(!quiet)saving=false;}}
  function openEditor(id,isTest=false){const rows=isTest?d.evaluationSamples:d.examples,row=rows.find(e=>e.id===id);if(!row)return;editing={id,isTest};const dialog=document.createElement('dialog');dialog.className='lesson-dialog';dialog.setAttribute('aria-labelledby','lesson-editor-title');dialog.innerHTML=`<form id="lesson-edit-form"><div class="lesson-dialog-top"><span class="eyebrow">${isTest?'KEPT OUT OF TRAINING':'TEACHING EXAMPLE'}</span><button type="button" data-lesson="close-editor" aria-label="Close editor">×</button></div><h2 id="lesson-editor-title">${isTest?'Review this test.':'Make this example right.'}</h2><label for="lesson-edit-question">${isTest?'A new test question':'Input or question'}</label><textarea id="lesson-edit-question" required maxlength="12000" rows="3">${esc(row.question)}</textarea><label for="lesson-edit-answer">${isTest?'Expected answer or criteria':'Desired answer'}</label><textarea id="lesson-edit-answer" required maxlength="24000" rows="6">${esc(row.answer)}</textarea>${!isTest?`<label for="lesson-edit-kind">Example type<select id="lesson-edit-kind">${Object.entries(exampleKinds).map(([id,label])=>`<option value="${id}" ${row.kind===id?'selected':''}>${label}</option>`).join('')}</select></label>`:''}${row.system?`<details><summary>Imported system instruction</summary><p>${esc(row.system)}</p></details>`:''}<div id="lesson-editor-error" role="alert"></div><div class="lesson-dialog-bottom"><button type="button" data-lesson="remove-row" class="lesson-text-action">Remove example</button><button class="button primary" type="submit">Save & approve ${icon('check')}</button></div></form>`;root.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>{editing=null;dialog.remove();});dialog.querySelector('textarea').focus();}

  root.addEventListener('input',event=>{const t=event.target;if(t.dataset.field){if(t.dataset.field==='name')d.name=t.value;else changeBrief(d,t.dataset.field,t.value);d.status='draft';notice='';}if(t.dataset.seed){editSeed(d,d.seeds[index].id,t.dataset.seed,t.value);root.querySelector('#lesson-seed-status').textContent='Needs your review';root.querySelector('#lesson-seed-status').className='lesson-status';root.querySelector('#lesson-seed-count').textContent=d.seeds.filter(e=>e.approved).length+' / '+d.seeds.length+' approved';root.querySelector('[data-lesson="approve-seed"]').innerHTML='This is the answer I want '+icon('check');}if(t.id==='lesson-model-search'){search=t.value;root.querySelector('#lesson-model-search-results').innerHTML=modelSearch();}},{signal:events.signal});
  root.addEventListener('change',async event=>{const t=event.target;try{if(t.id==='lesson-count')d.generationTarget=Number(t.value);if(t.id==='lesson-generation-model')d.generationModelId=t.value;if(t.id==='lesson-training-preset')d.trainingPreset=t.value;if(t.name==='lesson-delivery')d.delivery=t.value;if(t.id==='lesson-dataset-confirm')d.datasetConfirmed=t.checked&&checkDataset(d).ready;if(t.id==='lesson-result-test'){index=Number(t.value);paint();}if(['lesson-dataset-file','lesson-reference-file'].includes(t.id)){const file=t.files?.[0];if(!file)return;if(file.size>2_000_000)throw Error('Choose a file smaller than 2 MB.');const contents=await file.text();if(!alive)return;if(t.id==='lesson-reference-file'){if(!/\.(txt|md)$/i.test(file.name)||contents.includes('\u0000'))throw Error('Use a UTF-8 TXT or Markdown file. PDF and Word files need document processing first.');if(contents.length>12000)throw Error('Use up to 12,000 characters of reference text.');changeBrief(d,'source',contents);d.referenceName=file.name;}else{const rows=parseDataset(contents).map(e=>({...e,id:crypto.randomUUID(),kind:'everyday'}));d.examples=rows;d.datasetName=file.name;d.seeds=[];d.sourceMode='import';d.datasetBuilt=false;d.datasetStale=false;d.previewConfirmed=false;d.datasetConfirmed=false;}notice='File read locally. Saving to your account uploads your project and its content.';error='';paint();}}catch(e){showError(e);}},{signal:events.signal});
  root.addEventListener('submit',event=>{if(event.target.id!=='lesson-edit-form')return;event.preventDefault();if(!event.target.reportValidity()||!editing)return;const q=root.querySelector('#lesson-edit-question').value.trim(),a=root.querySelector('#lesson-edit-answer').value.trim(),{id,isTest}=editing;try{const issues=datasetIssues([{question:q,answer:a}]);if(issues.length)throw Error(issues[0]);if(isTest){const row=d.evaluationSamples.find(e=>e.id===id);Object.assign(row,{question:q,answer:a,approved:true,needsReplacement:false});invalidateDataset(d);}else{const row=d.examples.find(e=>e.id===id);if(row.question!==q||row.answer!==a||row.kind!==root.querySelector('#lesson-edit-kind').value)editDatasetRow(d,id,{question:q,answer:a,kind:root.querySelector('#lesson-edit-kind').value});row.approved=true;d.datasetConfirmed=false;}root.querySelector('dialog').close();notice='Example saved and approved.';paint();}catch(e){root.querySelector('#lesson-editor-error').textContent=e.message;}},{signal:events.signal});
  root.addEventListener('click',async event=>{const b=event.target.closest('[data-lesson]');if(!b||b.disabled||saving)return;const a=b.dataset.lesson;if((generating||running)&&!['cancel-job','refresh-job','export-data','export-tests','download-artifact','load-history'].includes(a))return;error='';notice='';try{
    if(a==='save'){await persist();paint();return;}
    if(a==='refresh-service'){await loadCapabilities();return;}
    if(a==='load-history'){await loadHistory();return;}
    if(a==='view-job-results'){if(d.gpuJob?.kind!=='training')return;d.stage=5;paint(true);if(!job)await checkJob();return;}
    if(a==='generate-preview'){await beginJob('generation','preview');return;}
    if(a==='refresh-job'){await checkJob();return;}
    if(a==='cancel-job'){await cancelJob();return;}
    if(a==='clear-job'){if(activeJob(d.gpuJob)||polling)return;d.gpuJob=null;job=null;syncBusy();await persist();paint();return;}
    if(a==='download-artifact'){const source=b.dataset.job?historyJobs?.find(row=>row.id===b.dataset.job):job,artifact=source?.artifacts?.find(x=>x.id===b.dataset.artifact);if(!artifact||source.status!=='succeeded')throw Error('This output is not available yet.');b.disabled=true;const blob=await client.artifact(source.id,artifact.id,{signal:events.signal});if(!alive)return;download(artifact.name,blob,blob.type||'application/octet-stream');notice='Training output downloaded. The adapter requires its pinned base model.';paint();return;}
    if(a==='task'){changeBrief(d,'task',b.dataset.task);paint();return;}
    if(a==='use-preset'){d.goal=taskTypes[d.task].goal;d.source=taskTypes[d.task].source;d.name=projectName(d);for(const row of d.seeds)row.approved=false;invalidateDataset(d,{seedChange:true});notice='Example task loaded. Replace illustrative details with your own.';paint();return;}
    if(a==='source-mode'){changeBrief(d,'sourceMode',b.dataset.sourceMode);paint();return;}
    if(a==='next'){const problem=validateTo(d.stage+1);if(problem)throw Error(problem);if(d.stage===1)makePreview(d);if(d.stage===2)d.previewConfirmed=true;d.stage++;index=0;paint(true);return;}
    if(a==='back'||a==='step'){const target=a==='back'?d.stage-1:Number(b.dataset.step);if(target<0||target>d.stage||running)return;d.stage=target;paint(true);return;}
    if(a==='seed-tab'){index=Number(b.dataset.index);paint();return;}
    if(a==='approve-seed'){approveSeed(d,d.seeds[index].id);const next=d.seeds.findIndex((e,i)=>i>index&&!e.approved);if(next>=0)index=next;notice=d.seeds.every(e=>e.approved)?'Preview approved. Next, prepare and review your complete dataset.':'Correction approved. Review the next example.';paint();return;}
    if(a==='build-dataset'){const issue=seedError(d);if(issue)throw Error(issue);if(d.sourceMode==='import'){prepareImportedDataset(d);notice='Imported dataset checked. Review every row before continuing.';paint();}else await beginJob('generation','dataset');return;}
    if(a==='filter'){filter=b.dataset.filter;page=0;paint();return;}
    if(a==='page'){page+=Number(b.dataset.direction);paint();return;}
    if(a==='approve-page'){const {visible,report}=dataRows();for(const row of visible)if(!report.rowProblems.has(row.id))row.approved=true;d.datasetConfirmed=false;notice='Reviewed rows on this page approved. Rows with issues stay unapproved.';paint();return;}
    if(a==='approve-import'){if(d.sourceMode!=='import')return;const report=checkDataset(d);for(const row of d.examples)if(!report.rowProblems.has(row.id))row.approved=true;d.datasetConfirmed=false;notice='Imported rows marked reviewed by you. Any flagged issues still need a fix.';paint();return;}
    if(a==='edit-row'||a==='edit-test'){openEditor(b.dataset.row,a==='edit-test');return;}
    if(a==='close-editor'){root.querySelector('dialog')?.close();return;}
    if(a==='remove-row'){if(!editing)return;const {id,isTest}=editing;if(isTest)d.evaluationSamples=d.evaluationSamples.filter(e=>e.id!==id);else{if(d.seeds.some(e=>e.id===id))throw Error('This is one of your preview examples. Change it in Teach by example so the dataset stays consistent.');d.examples=d.examples.filter(e=>e.id!==id);}invalidateDataset(d);root.querySelector('dialog').close();paint();return;}
    if(a==='suggest-tests'){d.evaluationSamples=suggestedTests(d);invalidateDataset(d);notice='Three illustrative test questions added. Check their facts and approve each one.';paint();return;}
    if(a==='add-test'){if(d.evaluationSamples.length>=50)throw Error('Keep at most 50 held-out test questions.');const row={id:crypto.randomUUID(),question:'',answer:'',approved:false,origin:'user-authored'};d.evaluationSamples.push(row);invalidateDataset(d);paint();openEditor(row.id,true);return;}
    if(a==='approve-test'){const row=d.evaluationSamples.find(e=>e.id===b.dataset.row);if(!row)return;if(!row.question.trim()||!row.answer.trim()||row.needsReplacement)throw Error('Edit this test question and its expected answer first.');row.approved=true;d.datasetConfirmed=false;paint();return;}
    if(a==='model'){d.modelId=b.dataset.model;paint();return;}
    if(a==='template'){download('macfit-dataset-template.jsonl','{"question":"What is your return policy?","answer":"Unused items can be returned within 30 days."}\n','application/x-ndjson');return;}
    if(a==='export-data'){if(!d.examples.length)throw Error('Prepare a dataset first.');download('macfit-training-dataset.jsonl',trainingFile(d),'application/x-ndjson');notice='Training file prepared. Test questions are kept separate.';paint();return;}
    if(a==='export-tests'){download('macfit-test-questions.jsonl',evaluationFile(d),'application/x-ndjson');notice='Separate test questions prepared for download.';paint();return;}
    if(a==='export-brief'){download('macfit-training-brief.json',JSON.stringify(lessonBrief(d,model()),null,2));notice='Training brief prepared. No job was submitted.';paint();return;}
    if(a==='start'){if(!root.querySelector('#lesson-run-confirm')?.checked)throw Error('Confirm the reviewed dataset and GPU training plan before starting.');await beginJob('training');return;}

    if(a==='improve'){if(activeJob(d.gpuJob))return;d.stage=3;d.status='draft';paint(true);return;}
  }catch(e){showError(e);}},{signal:events.signal});
  const stash=()=>{try{stashGuestDraft(d);}catch{}};document.addEventListener('macfit:account-will-change',stash,{signal:events.signal});
  paint();void loadCapabilities();if(d.gpuJob)void checkJob();return ()=>{alive=false;clearTimeout(timer);events.abort();};
}

export function teachingLibraryMarkup(catalog){
  let rows;try{rows=teachingProjects();}catch{return '<div class="teach-error">Your teaching projects could not be read.</div>';}
  return `<section class="teach-library"><div class="teach-library-heading"><div><span class="eyebrow">TAUGHT BY YOU</span><h2>Teaching projects</h2><p>Drafts, reviewed datasets and GPU job references saved to ${workspaceLocation()}.</p></div><a class="button primary" href="/teach">Teach a model ${icon('arrow')}</a></div>${rows.length?`<div class="teach-library-grid">${rows.map(raw=>{const d=upgradeDraft(raw);return `<article class="card teach-library-card"><span class="teach-preview">${d.gpuJob?'GPU job · '+esc(d.gpuJob.status):d.datasetBuilt?'Dataset in progress':'Draft'}</span><h3>${esc(d.name||taskTypes[d.task]?.title||'Untitled project')}</h3><p>${esc(catalog.models.find(m=>m.id===d.modelId)?.name||'Model selected after data review')}</p><small>${d.datasetBuilt?d.examples.length+' dataset examples':d.seeds.length+' preview examples'} · ${d.evaluationSamples.length} test questions</small><a class="button secondary" href="/teach?draft=${encodeURIComponent(d.id)}">${d.gpuJob?'Open project & check job':'Continue teaching'} →</a></article>`;}).join('')}</div>`:'<div class="teach-library-empty">Start with a task. Build a reviewed dataset. Teach a model your way of working.</div>'}</section>`;
}
